namespace mrs {
bool enum_lookup(const char* name, double* out) {
    int lo = 0, hi = kEnumCount - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int c = strcmp(name, kEnumTable[mid].name);
        if (c == 0) { *out = kEnumTable[mid].value; return true; }
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return false;
}
int enum_count() { return kEnumCount; }
const char* enum_name(int i) { return kEnumTable[i].name; }
double enum_value(int i) { return kEnumTable[i].value; }
}  // namespace mrs

